type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const state = { ...d.initial },
    subs = new Map<string, string[]>(),
    out: any[] = [];
  const emit = (id: string, keys: string[]): void => {
    out.push([id, keys.reduce((a: number, k: string) => a + state[k], 0)]);
  };
  for (const op of d.operations) {
    if (op.op === "autorun") {
      subs.set(op.id, op.keys);
      emit(op.id, op.keys);
    } else if (op.op === "dispose") subs.delete(op.id);
    else {
      const changed = state[op.key] !== op.value;
      state[op.key] = op.value;
      if (changed) for (const [id, keys] of subs) if (keys.includes(op.key)) emit(id, keys);
    }
  }
  return out;
}
